// Original indexmap2.14 range, truncate, Drain and hash-index mutation observer.
#![feature(panic_can_unwind,panic_internals)]
use indexmap::{IndexMap,map::Drain}; use serde_json::{json,Value};
use std::{cell::{Cell,RefCell},rc::Rc,hash::{Hash,Hasher,BuildHasher},io::{self,BufRead},panic::{self,AssertUnwindSafe},ops::{Bound,RangeBounds},mem::ManuallyDrop};
thread_local!{static TRACE:Cell<bool>=const{Cell::new(false)};}
struct Log{trace:bool,events:Vec<String>,fail:String,failed:bool}type L=Rc<RefCell<Log>>;
fn step(l:&L,s:String){let event=format!("{s}:{}",std::thread::panicking());let fail={let mut log=l.borrow_mut();log.events.push(event.clone());let yes=!log.failed&&log.fail==event;if yes{log.failed=true};yes};if l.borrow().trace{println!("E:{}",json!(event))}if fail{panic!("fail")}}
struct K{id:u64,log:L}impl Hash for K{fn hash<H:Hasher>(&self,h:&mut H){step(&self.log,format!("hash:{}",self.id));h.write_u64(self.id)}}impl PartialEq for K{fn eq(&self,r:&Self)->bool{step(&self.log,format!("eq:{}:{}",self.id,r.id));self.id==r.id}}impl Eq for K{}impl Drop for K{fn drop(&mut self){step(&self.log,format!("kdrop:{}",self.id))}}
struct V{id:u64,log:L}impl Drop for V{fn drop(&mut self){step(&self.log,format!("vdrop:{}",self.id))}}
struct B{log:L,mask:u64}struct H{log:L,mask:u64,state:u64}impl Hasher for H{fn write(&mut self,_:&[u8]){panic!("unexpected write")}fn write_u64(&mut self,n:u64){step(&self.log,format!("u64:{n}"));self.state=n}fn finish(&self)->u64{step(&self.log,"finish".into());self.state&self.mask}}impl Drop for H{fn drop(&mut self){step(&self.log,"hdrop".into())}}impl BuildHasher for B{type Hasher=H;fn build_hasher(&self)->H{step(&self.log,"build".into());H{log:self.log.clone(),mask:self.mask,state:0}}}impl Drop for B{fn drop(&mut self){step(&self.log,"bdrop".into())}}

impl Clone for B{fn clone(&self)->Self{step(&self.log,"bclone".into());Self{log:self.log.clone(),mask:self.mask}}}
fn n(q:&Value,k:&str)->usize{q[k].as_u64().unwrap_or(0)as usize}
fn pairs(map:&IndexMap<K,V,B>)->Value{json!(map.iter().map(|(k,v)|(k.id,v.id)).collect::<Vec<_>>())}
fn error(p:Box<dyn std::any::Any+Send>)->Value{if let Some(s)=p.downcast_ref::<String>(){json!(s)}else if let Some(s)=p.downcast_ref::<&str>(){json!(s)}else{json!("opaque")}}
fn query(map:&IndexMap<K,V,B>,count:usize,l:&L)->Value{json!((0..count).map(|id|{let key=ManuallyDrop::new(K{id:id as u64,log:l.clone()});map.get(&*key).map(|v|v.id)}).collect::<Vec<_>>())}
fn take(value:Option<(K,V)>)->Value{match value{Some(pair)=>{let out=json!([pair.0.id,pair.1.id]);drop(pair);out},None=>Value::Null}}
fn action(q:&Value)->Value{let l=Rc::new(RefCell::new(Log{trace:false,events:Vec::new(),fail:String::new(),failed:false}));let mut map=IndexMap::with_capacity_and_hasher(n(q,"capacity"),B{log:l.clone(),mask:q["mask"].as_u64().unwrap()});for id in 0..n(q,"n"){map.insert(K{id:id as u64,log:l.clone()},V{id:id as u64+10,log:l.clone()});}{let mut log=l.borrow_mut();log.events.clear();log.fail=q["fail"].as_str().unwrap_or("").into();}let mut holder=None;
let slot=Some(&mut map);let holder_ref=&mut holder;let logs=&l;
let result=panic::catch_unwind(AssertUnwindSafe(move||{let l=logs;let map=slot.unwrap();let holder=holder_ref;*holder=match q["method"].as_str().unwrap(){"first"=>map.first_entry(),"last"=>map.last_entry(),"occupied"=>match map.entry(K{id:n(q,"a")as u64,log:l.clone()}){indexmap::map::Entry::Occupied(e)=>Some(e.into()),indexmap::map::Entry::Vacant(e)=>{drop(e);None}},_=>map.get_index_entry(n(q,"a"))};let Some(e)=holder.as_mut()else{return Value::Null};match q["op"].as_str().unwrap(){"get"=>json!([e.index(),e.key().id,e.get().id]),"mutate"=>{e.get_mut().id+=1000;json!(e.get().id)},"insert"=>{let old=e.insert(V{id:1000,log:l.clone()});let out=json!(old.id);drop(old);out},"into_mut"=>{let v=holder.take().unwrap().into_mut();v.id+=1000;json!(v.id)},"swap_pair"=>take(Some(holder.take().unwrap().swap_remove_entry())),"shift_pair"=>take(Some(holder.take().unwrap().shift_remove_entry())),"swap_value"=>{let old=holder.take().unwrap().swap_remove();let out=json!(old.id);drop(old);out},"shift_value"=>{let old=holder.take().unwrap().shift_remove();let out=json!(old.id);drop(old);out},"move"=>{holder.take().unwrap().move_index(n(q,"b"));Value::Null},"swap"=>{holder.take().unwrap().swap_indices(n(q,"b"));Value::Null},_=>panic!("bad op")}}));let(value,error)=match result{Ok(value)=>(value,Value::Null),Err(p)=>(Value::Null,error(p))};let held=holder.as_ref().map(|e|(e.index(),e.key().id,e.get().id));drop(holder);let events=l.borrow().events.clone();{let mut log=l.borrow_mut();log.fail.clear();log.events.clear();}let entries=pairs(&map);let capacity=map.capacity();let queries=query(&map,n(q,"n")+2,&l);let query_events=l.borrow().events.clone();l.borrow_mut().events.clear();drop(map);let dropped=l.borrow().events.clone();json!({"value":value,"panic":error,"held":held,"events":events,"entries":entries,"capacity":capacity,"queries":queries,"query_events":query_events,"drop":dropped})}
struct OnDrop<F:FnOnce()>(Option<F>);impl<F:FnOnce()>Drop for OnDrop<F>{fn drop(&mut self){self.0.take().unwrap()()}}
fn run(q:&Value)->Value{if q["inherited"].as_bool().unwrap_or(false){let mut result=None;let _=panic::catch_unwind(AssertUnwindSafe(||{let _g=OnDrop(Some(||result=Some(action(q))));panic!("outer")}));result.unwrap()}else{action(q)}}
fn main(){panic::set_hook(Box::new(|_|{}));for line in io::stdin().lock().lines(){let q:Value=serde_json::from_str(&line.unwrap()).unwrap();println!("{}",json!({"request":q,"result":run(&q)}))}}
